package net.zartra.gui;
import org.bukkit.Bukkit;import org.bukkit.entity.Player;import java.lang.reflect.*;
final class VaultAdapter {private boolean warned;boolean available(){return Bukkit.getPluginManager().getPlugin("Vault")!=null;}boolean economyAvailable(){return provider("net.milkbowl.vault.economy.Economy")!=null;}boolean hasMoney(Player p,double amount){try{Object e=provider("net.milkbowl.vault.economy.Economy");return e!=null&&((Boolean)e.getClass().getMethod("has",org.bukkit.OfflinePlayer.class,double.class).invoke(e,p,amount)).booleanValue();}catch(Exception x){unavailable();return false;}}double balance(Player p){try{Object e=provider("net.milkbowl.vault.economy.Economy");if(e==null){unavailable();return -1D;}return ((Double)e.getClass().getMethod("getBalance",org.bukkit.OfflinePlayer.class).invoke(e,p)).doubleValue();}catch(Exception x){unavailable();return -1D;}}boolean setBalance(Player p,double target){if(target<0)return false;double current=balance(p);if(current<0)return false;return target>=current?deposit(p,target-current):withdraw(p,current-target);}boolean deposit(Player p,double amount){return economy(p,"depositPlayer",amount);}boolean withdraw(Player p,double amount){if(!hasMoney(p,amount))return false;return economy(p,"withdrawPlayer",amount);}boolean permission(Player p,String node,boolean add){try{Object e=provider("net.milkbowl.vault.permission.Permission");if(e==null){unavailable();return false;}Object r=e.getClass().getMethod(add?"playerAdd":"playerRemove",org.bukkit.entity.Player.class,String.class).invoke(e,p,node);return success(r);}catch(Exception x){unavailable();return false;}}private boolean economy(Player p,String method,double amount){if(amount<0)return false;try{Object e=provider("net.milkbowl.vault.economy.Economy");if(e==null){unavailable();return false;}return success(e.getClass().getMethod(method,org.bukkit.OfflinePlayer.class,double.class).invoke(e,p,amount));}catch(Exception x){unavailable();return false;}}private Object provider(String className){try{Class<?> type=Class.forName(className);Object registration=Bukkit.getServicesManager().getClass().getMethod("getRegistration",Class.class).invoke(Bukkit.getServicesManager(),type);return registration==null?null:registration.getClass().getMethod("getProvider").invoke(registration);}catch(Exception x){return null;}}private boolean success(Object response){try{return ((Boolean)response.getClass().getMethod("transactionSuccess").invoke(response)).booleanValue();}catch(Exception x){return false;}}String unavailable(){if(!warned){warned=true;Bukkit.getLogger().warning("[ZartraGUI] Vault economy/permission provider is unavailable; Vault action or condition was skipped.");}return "Vault provider unavailable";}static boolean validAmount(String value){try{double n=Double.parseDouble(value);return n>=0D&&!Double.isInfinite(n)&&!Double.isNaN(n);}catch(Exception e){return false;}}static boolean validNode(String value){return value!=null&&value.matches("[A-Za-z0-9_.-]{1,128}");}}